const body = $input.first().json.body || $input.first().json;

const employeeName = body.employeeName || body.name || 'Nguyen Van A';
const employeeEmail = body.employeeEmail || body.email || 'employee@company.com';
const department = body.department || 'Engineering';
const systemName = body.systemName || body.system || 'Production Database';
const accessLevel = body.accessLevel || 'Read-Write';
const reason = body.reason || 'Cần truy cập để bảo trì hệ thống và fix lỗi';

const requestId = `REQ-${Math.floor(100000 + Math.random() * 900000)}`;

return {
  requestId,
  employeeName,
  employeeEmail,
  department,
  systemName,
  accessLevel,
  reason,
  requestedAt: new Date().toISOString()
};

