const prev = $('Validate & Prepare Request').first().json;
const aiRaw = $input.first().json;

let text = '';
if (aiRaw.candidates?.[0]?.content?.parts?.[0]?.text) {
  text = aiRaw.candidates[0].content.parts[0].text;
} else {
  text = JSON.stringify(aiRaw);
}

text = text.replace(/```json\s*/gi, '').replace(/```\s*$/gi, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {
    riskLevel: "Medium",
    recommendation: "Manual Review",
    evaluationNote: "Yêu cầu cần quản lý IT xem xét thủ công trước khi cấp quyền."
  };
}

return {
  requestId: prev.requestId,
  employeeName: prev.employeeName,
  employeeEmail: prev.employeeEmail,
  department: prev.department,
  systemName: prev.systemName,
  accessLevel: prev.accessLevel,
  reason: prev.reason,
  riskLevel: parsed.riskLevel || "Medium",
  recommendation: parsed.recommendation || "Manual Review",
  evaluationNote: parsed.evaluationNote || "",
  status: "Pending Approval",
  createdAt: new Date().toISOString()
};

